#pragma once

// ui.icon's built-in icon set: the scene names of the LV_SYMBOL_* icons
// listed here, then every Wisp icon (wisp/ui/symbols.hpp, generated by
// tools/gen_icon_font.py) under its own name. One table for the schema's
// `name` enum (schema.cpp) and the symbol a name shows
// (scene_view_media.cpp). Every UI font draws all of them.

#include <array>
#include <cstddef>
#include <string_view>

#include "lvgl.h"
#include "wisp/ui/symbols.hpp"

namespace wisp::scene::icons {

struct IconSymbol {
    std::string_view name;
    const char* symbol;
};

inline constexpr IconSymbol kLvglIcons[] = {
    {"home", LV_SYMBOL_HOME},
    {"settings", LV_SYMBOL_SETTINGS},
    {"wifi", LV_SYMBOL_WIFI},
    {"battery", LV_SYMBOL_BATTERY_FULL},
    {"bell", LV_SYMBOL_BELL},
    {"play", LV_SYMBOL_PLAY},
    {"pause", LV_SYMBOL_PAUSE},
    {"stop", LV_SYMBOL_STOP},
    {"prev", LV_SYMBOL_PREV},
    {"next", LV_SYMBOL_NEXT},
    {"plus", LV_SYMBOL_PLUS},
    {"minus", LV_SYMBOL_MINUS},
    {"ok", LV_SYMBOL_OK},
    {"close", LV_SYMBOL_CLOSE},
    {"trash", LV_SYMBOL_TRASH},
    {"edit", LV_SYMBOL_EDIT},
    {"refresh", LV_SYMBOL_REFRESH},
    {"left", LV_SYMBOL_LEFT},
    {"right", LV_SYMBOL_RIGHT},
    {"up", LV_SYMBOL_UP},
    {"down", LV_SYMBOL_DOWN},
    {"upload", LV_SYMBOL_UPLOAD},
    {"download", LV_SYMBOL_DOWNLOAD},
    {"save", LV_SYMBOL_SAVE},
    {"list", LV_SYMBOL_LIST},
    {"image", LV_SYMBOL_IMAGE},
    {"audio", LV_SYMBOL_AUDIO},
    {"warning", LV_SYMBOL_WARNING},
    {"volume", LV_SYMBOL_VOLUME_MAX},
    {"mute", LV_SYMBOL_MUTE},
    {"envelope", LV_SYMBOL_ENVELOPE},
    {"eye", LV_SYMBOL_EYE_OPEN},
    {"eye_slash", LV_SYMBOL_EYE_CLOSE},
    {"bluetooth", LV_SYMBOL_BLUETOOTH},
    {"gps", LV_SYMBOL_GPS},
    {"power", LV_SYMBOL_POWER},
    {"bolt", LV_SYMBOL_CHARGE},
    {"phone", LV_SYMBOL_CALL},
    {"file", LV_SYMBOL_FILE},
    {"folder", LV_SYMBOL_DIRECTORY},
    {"keyboard", LV_SYMBOL_KEYBOARD},
    {"shuffle", LV_SYMBOL_SHUFFLE},
    {"loop", LV_SYMBOL_LOOP},
    {"copy", LV_SYMBOL_COPY},
    {"cut", LV_SYMBOL_CUT},
    {"paste", LV_SYMBOL_PASTE},
    {"drop", LV_SYMBOL_TINT},
};

inline constexpr size_t kIconCount = std::size(kLvglIcons) + std::size(ui::kWispIcons);

// Every name, the LV_SYMBOL_* ones first: the schema's enum.
inline constexpr std::array<std::string_view, kIconCount> kIconNames = [] {
    std::array<std::string_view, kIconCount> out{};
    size_t i = 0;
    for (const IconSymbol& icon : kLvglIcons) out[i++] = icon.name;
    for (const ui::WispIcon& icon : ui::kWispIcons) out[i++] = icon.name;
    return out;
}();

// The symbol `name` shows; "" for a name not in the set.
inline const char* symbol(std::string_view name) {
    for (const IconSymbol& icon : kLvglIcons)
        if (icon.name == name) return icon.symbol;
    for (const ui::WispIcon& icon : ui::kWispIcons)
        if (name == icon.name) return icon.symbol;
    return "";
}

}  // namespace wisp::scene::icons
